/* Learn through examples; build useful research materials without a paid API. */
(()=>{
 const C=window.REILibraryCore,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const session={question:{},search:{},papers:{},answers:{}},download=(name,text,type='text/markdown;charset=utf-8')=>{const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};
 let request=0,controller;
 const link=(href,label,cls='path-link')=>`<a class="${cls}" href="${href}" ${/^https:/.test(href)?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)} <span aria-hidden="true">↗</span></a>`;
 function shell(body,active='learn'){return `<div class="path-page library-page"><nav class="library-nav" aria-label="REI learning and creation">${link('#home','REI home')}${link('#learn','Learn',active==='learn'?'is-current':'')}${link('#create','Create',active==='create'?'is-current':'')}<details><summary>Saved work</summary>${link('#research','Research projects')}${link('#workbook','Learning workbook')}${link('#guided','Previous guided pathway')}${link('#backup','Backup and recovery')}</details></nav>${body}<footer class="path-help"><p>Examples and planning tools work locally. Tool inputs and challenge choices stay in this session; download useful results before closing. Your existing workbook and projects stay saved separately.</p>${link('#learning-evidence','Learning design and evidence')}</footer></div>`}
 function home(){return shell(`<header class="library-heading"><h1>See it work.<br><em>Then make it yours.</em></h1><p>Short lessons built around research decisions. See an example first, solve a small challenge and use a tool when you are ready. No long worksheet to unlock the next lesson.</p></header><div class="library-filters"><label>What do you need help with?<input type="search" data-library-search placeholder="Try sources, question, method or claims"></label><label>Category<select data-library-category><option value="all">All topics</option>${['Plan','Find','Read','Write'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><p class="path-muted" data-library-count role="status">Six short lessons</p><ol class="library-lessons">${C.lessons.map((x,i)=>`<li data-library-item data-category="${x.category}" data-search="${esc((x.title+' '+x.idea+' '+x.category).toLowerCase())}"><span class="path-number">${String(i+1).padStart(2,'0')}</span><div><small>${esc(x.category)} · ${x.time}</small><h2>${link('#library/'+x.id,x.title)}</h2><p>${esc(x.problem)}</p></div></li>`).join('')}</ol><p data-library-empty hidden>No lessons match. Try a broader term or choose All topics.</p><section class="library-bottom"><h2>Have something to work on?</h2><p>Create question options, build a search, find papers or organize a project.</p>${link('#create','Open Create','path-button')}</section>`)}
 function lesson(id){const x=C.lessons.find(x=>x.id===id);if(!x)return home();const index=C.lessons.indexOf(x),choice=session.answers[id];return shell(`<article class="library-lesson"><a class="path-back" href="#learn">← Learning library</a><p class="path-muted">Lesson ${index+1} of ${C.lessons.length} · ${x.category} · ${x.time}</p><h1>${esc(x.title)}</h1><p class="path-intro">${esc(x.problem)}</p><section><h2>The useful idea</h2><p>${esc(x.idea)}</p></section><section class="library-example"><h2>Watch the reasoning</h2><p>Fictional example—these are not reported research findings.</p><ol>${x.example.map(([title,body])=>`<li><strong>${esc(title)}</strong><p>${esc(body)}</p></li>`).join('')}</ol></section><section class="library-challenge"><h2>Your turn: make one decision</h2><p>${esc(x.scenario)}</p><fieldset><legend>Choose an answer to see the explanation</legend>${x.options.map((option,i)=>`<label class="library-choice"><input type="radio" name="library-choice" data-library-choice="${id}" value="${i}" ${choice===i?'checked':''}>${esc(option)}</label>`).join('')}</fieldset><div data-library-explanation role="status">${Number.isInteger(choice)?explanation(x,choice):'<p class="path-muted">No typing needed. Choose an option above.</p>'}</div></section><section><h2>Use the idea in your research</h2><p>${esc(x.transfer)}</p>${link(x.tool==='projects'?'#research':'#create/'+x.tool,x.tool==='projects'?'Open research projects':'Try the practical tool','path-button')}</section><details class="library-support"><summary>Read more and inspect the sources</summary><p>REI’s original example adapts the general guidance; it is not an experiment validating this lesson.</p>${x.source.map(id=>link(C.sources[id].url,C.sources[id].title)).join('')}${link('#lesson/'+x.lesson,'Open the detailed REI lesson')}</details><nav class="path-step-actions" aria-label="Continue through short lessons">${link('#learn','All short lessons')}${index<C.lessons.length-1?link('#library/'+C.lessons[index+1].id,'Next: '+C.lessons[index+1].title):link('#create','Next: make something useful')}</nav></article>`)}
 function explanation(x,i){return `<strong>${i===x.best?'A better fit for this situation.':'Check the evidence needed.'}</strong><p>${esc(x.why[i])}</p><p class="path-muted">Try the other option to compare. This is feedback on a fictional scenario, not a mastery score.</p>`}
 function create(){return shell(`<header class="library-heading"><h1>Less blank page.<br><em>More useful work.</em></h1><p>Choose a task. Get an explained starting point, a search you can use or real reference metadata. Then take it into your research project.</p></header><div class="library-create-list">${[['question','Shape a question and method','Compare question options and the evidence each aim needs.'],['search','Build a search strategy','Combine concepts and synonyms into a reusable database query.'],['papers','Find research papers','Search Crossref metadata and export selected references for your project.']].map(([id,title,body])=>`<section><h2>${link('#create/'+id,title)}</h2><p>${body}</p></section>`).join('')}<section><h2>${link('#research','Work with your sources')}</h2><p>Read PDFs, capture evidence, compare findings and develop a source-linked proposal.</p></section></div>`,'create')}
 const input=(key,label,value='',hint='')=>`<label>${label}${hint?`<small>${hint}</small>`:''}<input name="${key}" maxlength="180" required value="${esc(value)}"></label>`;
 function tool(id){if(!['question','search','papers'].includes(id))return create();const s=session[id],v=s.values||{};let body='';if(id==='question')body=`<h1>Find a workable<br><em>research direction.</em></h1><p>Choose an aim and add three specifics. The planner builds editable starting questions and explains the evidence needed. It does not establish novelty or select a valid method for you.</p><form data-library-form="question">${input('topic','What do you want to investigate?',v.topic,'A phenomenon or practice, such as study-app use')}${input('group','Who or what will you study?',v.group,'Such as first-year students; materials or documents also work')}${input('setting','Where or in which context?',v.setting,'Such as one campus or a defined set of records')}<label>What do you want to find out?<select name="aim">${Object.entries(C.aims).map(([id,a])=>`<option value="${id}" ${v.aim===id?'selected':''}>${a.label}</option>`).join('')}</select></label><button class="path-button">Build question options</button><button type="button" class="path-link" data-library-example="question">Try a filled example</button></form>`;
 if(id==='search')body=`<h1>Turn concepts<br><em>into a search.</em></h1><p>Put alternatives for the same concept together, separated by commas. The builder joins up to eight alternatives per group with OR and connects concepts with AND. It does not invent synonyms.</p><form data-library-form="search">${input('one','Concept 1 and alternatives',v.one,'Example: commuter, commuting')}${input('two','Concept 2 and alternatives',v.two,'Example: student, undergraduate')}<label>Optional concept 3<input name="three" maxlength="180" value="${esc(v.three||'')}" placeholder="Example: study planning, time management"></label><button class="path-button">Build my search</button><button type="button" class="path-link" data-library-example="search">Try a filled example</button></form>`;
 if(id==='papers')body=`<h1>Find papers.<br><em>Keep the real details.</em></h1><p>Search scholarly metadata from Crossref. Results are relevance candidates, not endorsements. Metadata may be incomplete; full text and abstracts are not supplied here.</p><form data-library-form="papers"><label>Topic, title or bibliographic words<input type="search" name="query" required minlength="3" maxlength="180" value="${esc(v.query||'')}" placeholder="Example: commuter students study time"></label><label>Record type<select name="type"><option value="journal-article" ${v.type!=='all'?'selected':''}>Journal articles</option><option value="all" ${v.type==='all'?'selected':''}>All scholarly record types</option></select></label><p class="path-muted">Searching sends this query to Crossref. Your workbook and project text are not sent. Publisher links open an external site.</p><button class="path-button">Find papers</button></form>`;
 return shell(`<article class="library-tool"><a href="#create" class="path-back">← Create</a>${body}<p data-library-tool-status role="status">${s.status||'Results are kept in this session. Download anything you want to keep.'}</p><section data-library-output tabindex="-1" aria-label="Tool results">${result(id)}</section></article>`,'create')}
 function result(id){const s=session[id],r=s.result;if(!r)return '';if(id==='question')return `<h2>Two possible directions</h2><p class="path-muted">Rule-based suggestions using your inputs. Replace any bracketed placeholders. Review the wording and evidence with a supervisor.</p><ol>${r.questions.map(q=>`<li><p>${esc(q)}</p></li>`).join('')}</ol><h3>Method starting point</h3><p>${esc(r.method)}</p><h3>What you would need</h3><p>${esc(r.needs)}</p><h3>What this cannot establish by itself</h3><p>${esc(r.limit)}</p><h3>Before committing</h3><ul>${r.next.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="path-button" data-library-export="question">Download this planning note</button>${link('#library/method','See the method worked example')}`;
 if(id==='search')return `<h2>Your Boolean starting query</h2><pre>${esc(r.query)}</pre><p>Too few results? Try this broader two-concept version:</p><pre>${esc(r.broad)}</pre><p>${esc(r.notes)}</p><div class="path-actions">${link(r.pubmed,'Search in PubMed')}${link(r.crossref,'Search metadata in Crossref')}</div><p>External searches send the terms to the chosen service. Check how the service interpreted them, record filters and revise after inspecting results.</p><button class="path-button" data-library-export="search">Download search strategy</button>`;
 if(!r.length)return '<h2>No records found</h2><p>Try fewer terms, a broader concept or an exact title. Your institution’s subject databases may cover different material.</p>';
 return `<h2>Check these sources</h2><p>Up to eight Crossref records. Check the original study, publication details and fit before citing. Select records to export.</p><div class="library-paper-list">${r.map((x,i)=>`<article><label><input type="checkbox" data-library-paper="${i}" ${x.title?'':'disabled'}><strong>${esc(x.title||'Title unavailable; inspect the publisher record')}</strong></label><p>${esc(x.authors.join('; ')||'Authors unavailable')} · ${esc(x.year||'Year unavailable')}</p><p>${esc(x.venue||'Venue unavailable')} · ${esc(x.type)}</p>${x.url?link(x.url,'Open DOI / publisher record'):'<p>DOI unavailable</p>'}</article>`).join('')}</div><button class="path-button" data-library-export="papers">Download selected references (.ris)</button><p>Then open a project → Library → Choose reference file. Inspect the import preview before saving. This exports metadata, not article PDFs.</p>${link('#research','Open research projects')}`}
 function render(parts){return parts[0]==='create'?(parts[1]?tool(parts[1]):create()):parts[0]==='library'&&parts[1]?lesson(parts[1]):home()}
 function update(id){const out=document.querySelector('[data-library-output]');if(out){out.innerHTML=result(id);out.focus({preventScroll:true})}}
 document.addEventListener('change',e=>{if(e.target.matches('[data-library-choice]')){const id=e.target.dataset.libraryChoice,x=C.lessons.find(x=>x.id===id),i=Number(e.target.value);if(!x||!x.options[i])return;session.answers[id]=i;document.querySelector('[data-library-explanation]').innerHTML=explanation(x,i)}if(e.target.matches('[data-library-category]'))filter();const form=e.target.closest('[data-library-form]');if(form)session[form.dataset.libraryForm].values=Object.fromEntries(new FormData(form))});
 function filter(){const q=(document.querySelector('[data-library-search]')?.value||'').toLowerCase(),category=document.querySelector('[data-library-category]')?.value||'all';let count=0;document.querySelectorAll('[data-library-item]').forEach(x=>{x.hidden=!(x.dataset.search.includes(q)&&(category==='all'||x.dataset.category===category));if(!x.hidden)count++});const countBox=document.querySelector('[data-library-count]');if(countBox)countBox.textContent=count+' matching lessons';const empty=document.querySelector('[data-library-empty]');if(empty)empty.hidden=count>0}
 document.addEventListener('input',e=>{if(e.target.matches('[data-library-search]'))filter();const form=e.target.closest('[data-library-form]');if(form)session[form.dataset.libraryForm].values=Object.fromEntries(new FormData(form))});
 document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-library-form]'))return;e.preventDefault();const id=form.dataset.libraryForm;if(id==='papers'&&form.querySelector('button').disabled)return;const values=Object.fromEntries(new FormData(form)),s=session[id],status=document.querySelector('[data-library-tool-status]');s.values=values;try{if(id!=='papers'){s.result=id==='question'?C.plan(values):C.search(values);status.textContent='Built from your inputs. Review the suggestions below.';update(id);return}if(values.query.trim().length<3)throw Error('Enter at least three characters.');controller?.abort();controller=new AbortController();const localController=controller,ticket=++request,button=form.querySelector('button');button.disabled=true;status.textContent='Searching Crossref…';const timer=setTimeout(()=>localController.abort(),15000);try{const response=await fetch('https://api.crossref.org/works?query.bibliographic='+encodeURIComponent(values.query.trim())+'&rows=8'+(values.type==='all'?'':'&filter=type:journal-article'),{signal:localController.signal});if(!response.ok)throw Error(response.status===429?'Crossref is rate limiting requests. Wait before retrying.':'Crossref is unavailable. Try again later.');const data=await response.json();if(ticket!==request||!form.isConnected)return;s.result=C.records(data);status.textContent=s.result.length+' records returned. Inspect the details before using them.';update(id)}finally{clearTimeout(timer);if(form.isConnected)button.disabled=false}}catch(error){if(form.isConnected)status.textContent=error.name==='AbortError'?'Search stopped or timed out. Retry, or use the search builder and your library databases.':error.message}});
 document.addEventListener('click',e=>{const example=e.target.closest('[data-library-example]');if(example){const id=example.dataset.libraryExample,form=example.closest('form'),values=id==='question'?{topic:'study-app use',group:'first-year students',setting:'one campus',aim:'experience'}:{one:'commuter, commuting',two:'student, undergraduate',three:'study planning, time management'};Object.entries(values).forEach(([key,value])=>form.elements.namedItem(key).value=value);form.requestSubmit();return}const button=e.target.closest('[data-library-export]');if(!button)return;const id=button.dataset.libraryExport,s=session[id];if(!s.result)return;if(id==='papers'){const chosen=[...document.querySelectorAll('[data-library-paper]:checked')].map(x=>s.result[Number(x.dataset.libraryPaper)]).filter(Boolean);if(!chosen.length){document.querySelector('[data-library-tool-status]').textContent='Select at least one reference to download.';return}download('rei-selected-references.ris',C.ris(chosen),'application/x-research-info-systems');}else{const r=s.result,text=id==='question'?'# Research planning note\n\nRule-based starting suggestions; not a validated research design.\n\n'+r.questions.join('\n\n')+'\n\n## Method\n'+r.method+'\n\n## Evidence needed\n'+r.needs+'\n\n## Limits\n'+r.limit+'\n\n## Next checks\n'+r.next.join('\n'):'# Search strategy\n\n'+r.query+'\n\nBroader version:\n'+r.broad+'\n\n'+r.notes+'\n\nRecord the database, date, filters and actual results after searching.\n';download('rei-'+id+'-note.md',text)}document.querySelector('[data-library-tool-status]').textContent='Download requested. Check the downloaded file before leaving.'});
 addEventListener('rrh:route',()=>{request++;controller?.abort()});
 window.REILibrary={render,home};
})();
